  &reftitle.examples;



    Ottenere tutti i numeri di telefono da un testo.


<?php
preg_match_all("/\(?  (\d{3})?  \)?  (?(1)  [\-\s] ) \d{3}-\d{4}/x",
                "Chiama il 555-1212 o il 1-800-555-1212", $phones);
?>







    Trovare i tag HTML corrispondenti (greedy)


<?php
// \\2 è un esempio di riferimento all'indietro. Indica a pcre che
// deve trovare una corrispondenza con la seconda coppia di parentesi dell'espressione regolare
// stessa, che in questo caso sarebbe ([\w]+). Il backslash aggiuntivo è
// necessario perché la stringa è tra doppi apici.
$html = "<b>testo in grassetto</b><a href=howdy.html>clicca qui</a>";

preg_match_all("/(<([\w]+)[^>]*>)(.*?)(<\/\\2>)/", $html, $matches, PREG_SET_ORDER);

foreach ($matches as $val) {
    echo "corrispondenza: " . $val[0] . "\n";
    echo "parte 1: " . $val[1] . "\n";
    echo "parte 2: " . $val[2] . "\n";
    echo "parte 3: " . $val[3] . "\n";
    echo "parte 4: " . $val[4] . "\n\n";
}
?>


    &example.outputs;


corrispondenza: <b>testo in grassetto</b>
parte 1: <b>
parte 2: b
parte 3: testo in grassetto
parte 4: </b>

corrispondenza: <a href=howdy.html>clicca qui</a>
parte 1: <a href=howdy.html>
parte 2: a
parte 3: clicca qui
parte 4: </a>







    Uso di sotto-pattern con nome


<?php

$str = <<<FOO
a: 1
b: 2
c: 3
FOO;

preg_match_all('/(?P<name>\w+): (?P<digit>\d+)/', $str, $matches);

/* Alternativa */
// preg_match_all('/(?<name>\w+): (?<digit>\d+)/', $str, $matches);

print_r($matches);

?>


    &example.outputs;


Array
(
    [0] => Array
        (
            [0] => a: 1
            [1] => b: 2
            [2] => c: 3
        )

    [name] => Array
        (
            [0] => a
            [1] => b
            [2] => c
        )

    [1] => Array
        (
            [0] => a
            [1] => b
            [2] => c
        )

    [digit] => Array
        (
            [0] => 1
            [1] => 2
            [2] => 3
        )

    [2] => Array
        (
            [0] => 1
            [1] => 2
            [2] => 3
        )

)
